const { withAppBuildGradle } = require("@expo/config-plugins");

/**
 * Release signing for the Android build.
 *
 * `android/` is generated by `expo prebuild`, so signing has to be applied by a
 * config plugin or it is lost on the next prebuild. This plugin patches
 * `app/build.gradle` to add a `release` signingConfig that reads the upload key
 * from the environment:
 *
 *   MULTICA_UPLOAD_STORE_FILE      absolute path to the .jks
 *   MULTICA_UPLOAD_STORE_PASSWORD  keystore password
 *   MULTICA_UPLOAD_KEY_ALIAS       key alias (default: multica-upload)
 *   MULTICA_UPLOAD_KEY_PASSWORD    key password (default: store password)
 *
 * If MULTICA_UPLOAD_STORE_FILE is unset the release buildType falls back to the
 * debug key, so a machine without the key can still assemble a testable APK.
 * Nothing secret is written into the repository — only the variable names are.
 *
 * Without this, `assembleRelease` produces an APK signed by
 * CN=Android Debug, which cannot be updated in place by a properly signed
 * build later and cannot be uploaded anywhere.
 */

const DEBUG_SIGNING = `    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
    }`;

const RELEASE_SIGNING = `    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
        // Upload key. Path and passwords come from the environment at build
        // time so the keystore never enters the repo.
        release {
            def storePath = System.getenv("MULTICA_UPLOAD_STORE_FILE")
            if (storePath) {
                storeFile file(storePath)
                storePassword System.getenv("MULTICA_UPLOAD_STORE_PASSWORD")
                keyAlias System.getenv("MULTICA_UPLOAD_KEY_ALIAS") ?: "multica-upload"
                keyPassword System.getenv("MULTICA_UPLOAD_KEY_PASSWORD") ?: System.getenv("MULTICA_UPLOAD_STORE_PASSWORD")
            }
        }
    }`;

const RELEASE_BLOCK_OLD = `        release {
            // Caution! In production, you need to generate your own keystore file.
            // see https://reactnative.dev/docs/signed-apk-android.
            signingConfig signingConfigs.debug`;

const RELEASE_BLOCK_NEW = `        release {
            signingConfig System.getenv("MULTICA_UPLOAD_STORE_FILE") ? signingConfigs.release : signingConfigs.debug`;

function patchGradle(contents) {
  let out = contents;

  if (!out.includes("System.getenv(\"MULTICA_UPLOAD_STORE_FILE\")")) {
    if (out.includes(DEBUG_SIGNING)) {
      out = out.replace(DEBUG_SIGNING, RELEASE_SIGNING);
    } else {
      throw new Error(
        "with-release-signing: could not find the signingConfigs block in app/build.gradle",
      );
    }
    if (out.includes(RELEASE_BLOCK_OLD)) {
      out = out.replace(RELEASE_BLOCK_OLD, RELEASE_BLOCK_NEW);
    } else {
      throw new Error(
        "with-release-signing: could not find the release buildType in app/build.gradle",
      );
    }
  }

  return out;
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== "groovy") {
      throw new Error("with-release-signing: expected a Groovy build.gradle");
    }
    cfg.modResults.contents = patchGradle(cfg.modResults.contents);
    return cfg;
  });
};

module.exports.patchGradle = patchGradle;
